"use strict";(globalThis.webpackChunkuaro_org_ua||=[]).push([[3712],{1623(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>c,frontMatter:()=>r,metadata:()=>o,toc:()=>h});const o=JSON.parse('{"id":"radio_101/getting-a-call-sign","title":"Getting a callsign","description":"Sooner or later, anyone who has listened to radio amateurs on the air starts to want an","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/radio_101/getting-a-call-sign.md","sourceDirName":"radio_101","slug":"/radio_101/getting-a-call-sign","permalink":"/en/docs/radio_101/getting-a-call-sign","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"What are the Regulations for amateur radio communication in Ukraine?","permalink":"/en/docs/radio_101/regulations-of-amateur-radio-communications-of-ukraine"},"next":{"title":"On-air etiquette","permalink":"/en/docs/radio_101/ethics-on-the-air"}}');var a=n(4848),i=n(8453);const r={sidebar_position:2},s="Getting a callsign",l={},h=[];function d(e){const t={a:"a",del:"del",h1:"h1",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"getting-a-callsign",children:"Getting a callsign"})}),"\n",(0,a.jsx)(t.p,{children:"Sooner or later, anyone who has listened to radio amateurs on the air starts to want an\nofficial callsign of their own, to join the community, to get on the bands and to enjoy\nthose first contacts. Where to go and what to do \u2014 there is honestly not much information\nabout this online. But it is all doable, and here are a few pointers."}),"\n",(0,a.jsxs)(t.p,{children:["First, read the Regulations for amateur radio communication in Ukraine carefully. This is\nthe document that governs everything happening in the amateur radio universe \u2014 the rules,\nthe boundaries and the procedures, so to speak. It genuinely contains 99% of the answers to\nthe questions that come up. On top of that, you need to know its main provisions, because\nthey are what the interview or the examination will be about.\n",(0,a.jsx)(t.a,{href:"https://zakon.rada.gov.ua/laws/show/z1106-23#Text",children:"https://zakon.rada.gov.ua/laws/show/z1106-23#Text"})]}),"\n",(0,a.jsx)(t.p,{children:"Second, look carefully around you: through mutual acquaintances you will almost certainly\nfind someone with a callsign who can give you practical advice on where to go locally \u2014 the\naddress of the local radio club or club station. They will be glad to see you there,\nbelieve me, if they see the willingness and the spark in your eyes. I know of a case where\nsomeone came up on the local repeater and said outright that they had no licence but\nwanted one. They were helped and told what to do."}),"\n",(0,a.jsx)(t.p,{children:"And if that does not work, there is the official route \u2014 longer and less colourful. It may\ngo faster or slower, and some offices accept electronic copies of documents. You will find\nthat out as you go. What follows is the most general and longest version of the procedure."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Make paper copies of your passport and your tax identification number."}),"\n",(0,a.jsx)(t.li,{children:"Take Annex 7 from the regulations, print it out and fill it in (you can prepare Annexes 8\nand 9 at the same time, or fill them in at the interview or examination)."}),"\n",(0,a.jsx)(t.li,{children:"Optional, but very effective: write a short free-form letter about yourself and your wish\nto get on the air and develop as an operator.\nFind the address of your regional UCRF (Ukrainian State Centre of Radio Frequencies)\noffice and send everything there by registered post. Then wait for a reply. As a rule\nthis is a follow-up phone call, where, besides a few questions about the documents, you\nwill most likely be given the approximate or exact date and place of the qualification\ncommittee meeting (see the regulations for what that is). Once the UCRF accepts the\napplication, the date and time of the interview or examination will be agreed within a\nmonth. You will need to travel there for a conversation (if you are applying for class C)\nor possibly to sit an examination for the higher classes.\nSome time after the examination the UCRF will send an invoice for its services (as of\nmid-2024 this was around 130 UAH), and a few days after payment you will receive the\nlicence with your callsign that you have been waiting for."}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.strong,{children:"Important details:"})}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Under the regulations, if you live somewhere other than your registered address, you\nstill have to apply at your registered address. Yes, there have been cases of people\ngetting licensed in other regions, but each such case has to be discussed with the local\nUCRF separately."}),"\n",(0,a.jsx)(t.li,{children:"However! Under the regulations you may sit the interview or examination at any\nqualification committee, obtain the Annex 6 certificate on the strength of the result,\nand send that instead of Annex 7 together with the rest of the documents to your local\nUCRF to obtain the licence. This works \u2014 tested personally."}),"\n",(0,a.jsx)(t.li,{children:'The most frequent question is what to enter in the table in Annex 8. The truth! Got a\nBaofeng \u2014 write it down. Got an HF transceiver \u2014 write it down. If in doubt, write\n"homebrew" and "no serial number", along with the bands and power in line with the\nregulations.'}),"\n",(0,a.jsxs)(t.li,{children:["If the applicant is a minor, a free-form statement from the parents must be added to the\ndocuments above, saying that they have no objection ",(0,a.jsx)(t.del,{children:"and are in fact delighted that the\nchild would rather throw an antenna up a willow tree than sit on TikTok"})]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"It may all look complicated and utterly impossible, but only at first glance. I hope to\nmeet on the air those whom this advice has helped."})]})}function c(e={}){const{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var o=n(6540);const a={},i=o.createContext(a);function r(e){const t=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);